import itertools

def minPath(grid, k):
    n = len(grid)
    min_val = float('inf')
    best_path = None

    for start_r in range(n):
        for start_c in range(n):
            start_val = grid[start_r][start_c]
            if start_val > min_val:
                continue

            current_path = [start_val]
            current_r, current_c = start_r, start_c

            for _ in range(k - 1):
                neighbors = []
                if current_r > 0:
                    neighbors.append((current_r - 1, current_c))
                if current_r < n - 1:
                    neighbors.append((current_r + 1, current_c))
                if current_c > 0:
                    neighbors.append((current_r, current_c - 1))
                if current_c < n - 1:
                    neighbors.append((current_r, current_c + 1))

                best_next = None
                best_next_val = float('inf')

                for nr, nc in neighbors:
                    val = grid[nr][nc]
                    if val < best_next_val:
                        best_next_val = val
                        best_next = (nr, nc)

                if best_next is None:
                    break

                current_path.append(best_next_val)
                current_r, current_c = best_next

            if current_path < best_path:
                best_path = current_path
                min_val = current_path[0]

    return best_path
```

