        return []
    if n == 0:
        return [1]

    sequence = [1, 3]

    for i in range(2, n + 1):
        if i % 2 == 0:
            val = 1 + i // 2
        else:
            if len(sequence) < i + 1:
                sequence.append(0)
            val = sequence[i - 1] + sequence[i - 2] + sequence[i + 1]
        sequence.append(val)

