        while j <= right:
            temp[k] = arr[j]
            j += 1
            k += 1
        for idx in range(left, right + 1):
            arr[idx] = temp[idx]
        return inv_count

    temp = [0] * n
    return merge_sort(arr, temp, 0, n - 1)
