def amicable_numbers_sum(limit):
    def get_divisor_sum(n):
        if n <= 1:
            return 0
        divisors = [1]
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:
                    divisors.append(n // i)
        return sum(divisors)

    amicable_pairs = set()
    for i in range(2, limit + 1):
        d_i = get_divisor_sum(i)
        if d_i == i:
            continue
        if d_i >= limit:
            continue
        d_d_i = get_divisor_sum(d_i)
        if d_d_i == i and i != d_i:
            amicable_pairs.add(min(i, d_i))
            amicable_pairs.add(max(i, d_i))

    return sum(amicable_pairs)
