def max_path_sum(tri, m, n):
    for i in range(m - 1, -1, -1):
        for j in range(n):
            if j == 0:
                tri[i][j] += tri[i + 1][j]
            elif j == n - 1:
                tri[i][j] += tri[i + 1][j + 1]
            else:
                tri[i][j] += max(tri[i + 1][j], tri[i + 1][j + 1])
    return tri[0][0]
