def is_num_keith(x):
    if x <= 0:
        return False
    if x == 1:
        return True
    digits = list(str(x))
    if len(digits) == 1:
        return True
    window = digits[:]
    for _ in range(len(digits) - 1):
        new_digit = sum(int(d) for d in window) % 10
        window.pop(0)
        window.append(str(new_digit))
        if int(''.join(window)) == x:
            return True
    return False
```

