def find_longest_repeating_subseq(s: str) -> int:
    n = len(s)
    if n < 2:
        return 0

    # dp[i][j] will store the length of the longest repeating subsequence
    # using characters from s[0..i-1] and s[0..j-1]
    # where i != j (to ensure different positions)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j:
                # Cannot use same index for both subsequences
                dp[i][j] = 0
            elif s[i - 1] == s[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][n]
```

