def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if m < 1:
        return 0

    count = 0
    for start in range(1, m + 1):
        current = start
        steps = 0
        while steps < n:
            if current > m:
                break
            lower = current * 2
            upper = m
            if lower > upper:
                break
            count += (upper - lower + 1)
            current = lower
            steps += 1
    return count
```

