def count_no_of_ways(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k

    prev2 = k * (k - 1)
    prev1 = k * k

    for _ in range(3, n + 1):
        current = prev1 * (k - 1) + prev2 * k
        prev2 = prev1
        prev1 = current

    return prev1
```

