def max_sub_array_sum_repeated(a, n, k):
    if n == 0:
        return 0
    if k == 1:
        max_so_far = float('-inf')
        current_max = 0
        for x in a:
            current_max += x
            max_so_far = max(max_so_far, current_max)
            current_max = max(0, current_max)
        return max_so_far

    total_sum = sum(a)
    if total_sum > 0:
        return total_sum * k + max_sub_array_sum_repeated(a, n, 1)

    max_so_far = float('-inf')
    current_max = 0
    for x in a:
        current_max += x
        max_so_far = max(max_so_far, current_max)
        current_max = max(0, current_max)

    return max_so_far + max_so_far
