def intersection_nested_lists(l1, l2):
    """
    Finds elements present in both l1 and any nested list within l2.
    Returns a list of lists, where each inner list contains the matching elements
    from l2's nested structure, preserving the order of appearance in l2.
    """
    result = []
    seen = set()

    for nested in l2:
        if isinstance(nested, list):
            for item in nested:
                if item in l1 and item not in seen:
                    result.append([item])
                    seen.add(item)
        elif isinstance(item, list):
            for sub_item in item:
                if sub_item in l1 and sub_item not in seen:
                    result.append([sub_item])
                    seen.add(sub_item)

    return result
```

