def find_minimum_range(lists):
    if not lists:
        return None

    min_val = float('inf')
    max_val = float('-inf')
    min_idx = 0
    max_idx = 0
    n = len(lists)
    m = len(lists[0])

    nodes = []
    for i in range(n):
        for j in range(m):
            nodes.append(Node(lists[i][j], i, j))

    nodes.sort()

    result = (float('inf'), float('inf'))

    for i in range(len(nodes)):
        node = nodes[i]
        min_val = node.value
        max_val = node.value

        for j in range(n):
            if j != node.list_num:
                idx = node.index
                while idx < m and lists[j][idx] < max_val:
                    max_val = lists[j][idx]
                    idx += 1
                if idx < m:
                    max_val = lists[j][idx]

        if max_val - min_val < result[1] - result[0]:
            result = (min_val, max_val)

    return result
```

