def pancake_sort(nums):
    n = len(nums)
    k = n
    while k > 1:
        max_idx = nums.index(max(nums[:k]))
        if max_idx != k - 1:
            if max_idx != 0:
                nums[:max_idx + 1] = nums[:max_idx + 1][::-1]
            nums[:k] = nums[:k][::-1]
        k -= 1
    return nums
