def find_Min(arr, low, high):
    if not arr:
        return None

    if low == high:
        return arr[low]

    if arr[low] < arr[high]:
        return arr[low]

    mid = (low + high) // 2

    if arr[mid] > arr[high]:
        return find_Min(arr, mid + 1, high)
    elif arr[mid] < arr[low]:
        return arr[mid]
    else:
        return min(find_Min(arr, low, mid), find_Min(arr, mid + 1, high))
