def get_max_sum(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1

    memo = {1: 1}

    def helper(x):
        if x in memo:
            return memo[x]

        val = x
        if x % 2 == 0:
            val = max(val, helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5))
        elif x % 3 == 0:
            val = max(val, helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5))
        elif x % 4 == 0:
            val = max(val, helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5))
        elif x % 5 == 0:
            val = max(val, helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5))

        memo[x] = val
        return val

    return helper(n)
