from typing import Optional

class Node:
    def __init__(self, data):
        self.data = data
        self.left: Optional['Node'] = None
        self.right: Optional['Node'] = None

def get_height(root: Optional[Node]) -> int:
    if root is None:
        return 0
    return 1 + max(get_height(root.left), get_height(root.right))

def is_tree_balanced(root: Optional[Node]) -> bool:
    def check_balance(node: Optional[Node]) -> Optional[int]:
        if node is None:
            return 0

        left_height = check_balance(node.left)
        if left_height is None:
            return None

        right_height = check_balance(node.right)
        if right_height is None:
            return None

        if abs(left_height - right_height) > 1:
            return None

        return 1 + max(left_height, right_height)

    return check_balance(root) is not None
```

