def rearrange_bigger(n):
    digits = list(str(n))
    if len(digits) == 1:
        return -1
    digits.sort()
    if digits[-1] == digits[-2]:
        return -1
    i = len(digits) - 2
    while i >= 0 and digits[i] >= digits[-1]:
        i -= 1
    if i < 0:
        return -1
    digits[i], digits[-1] = digits[-1], digits[i]
    digits[i+1:] = sorted(digits[i+1:])
    return int("".join(digits))
