def get_ludic(n):
    if n < 1:
        return []
    if n == 1:
        return [1]

    ludic = [1] * (n + 1)
    ludic[0] = 0
    ludic[1] = 1
    primes = [1]
    next_prime = 1

    for i in range(2, n + 1):
        if ludic[i] == 0:
            primes.append(i)
            next_prime = i
        for p in primes:
            if i * p > n:
                break
            ludic[i * p] = 0
            if i == next_prime:
                break

    result = []
    for i in range(1, n + 1):
        if ludic[i] != 0:
            result.append(i)

    return result
