        return 0

    n = len(arr)
    inc = [1] * n
    dec = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] < arr[j]:
                dec[i] = max(dec[i], dec[j] + 1)

