def group_tuples(Input):
    from collections import defaultdict

    groups = defaultdict(list)
    for t in Input:
        groups[t[0]].append(t)

    result = []
    for key in sorted(groups.keys()):
        if len(groups[key]) == 1:
            result.append(groups[key][0])
        else:
            first = groups[key][0]
            others = [t for t in groups[key] if t != first]
