def find_kth(arr1, arr2, m, n, k):
    if k == 1:
        return min(arr1[0], arr2[0])

    i, j = 0, 0
    while True:
        if i == m:
            return arr2[j + k - 1]
        if j == n:
            return arr1[i + k - 1]
        if i + k - 1 >= m:
            return arr2[j + k - 1]
        if j + k - 1 >= n:
            return arr1[i + k - 1]

        x1 = arr1[i + k // 2 - 1]
        x2 = arr2[j + k // 2 - 1]

        if x1 < x2:
            i += k // 2
            k -= k // 2
        else:
            j += k // 2
            k -= k // 2
