def max_chain_length(arr, n):
    if n == 0:
        return 0

    # Sort pairs by their first element
    sorted_pairs = sorted(arr, key=lambda x: x.a)

    # dp[i] will store the maximum chain length ending at index i
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            # If pair j can be followed by pair i
            if sorted_pairs[j].b < sorted_pairs[i].a:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
