import heapq

def maximum_product(nums):
    if len(nums) < 3:
        raise ValueError("Input list must contain at least three numbers.")

    min_heap = []
    max_heap = []

    for num in nums:
        heapq.heappush(min_heap, num)
        heapq.heappush(max_heap, -num)

    if len(min_heap) > 3:
        heapq.heappop(min_heap)
    if len(max_heap) > 3:
        heapq.heappop(max_heap)

    sorted_nums = sorted(nums)
    n = len(sorted_nums)

    if n == 3:
        return sorted_nums[0] * sorted_nums[1] * sorted_nums[2]
    elif n == 4:
        return sorted_nums[0] * sorted_nums[1] * sorted_nums[3]
    else:
        return sorted_nums[0] * sorted_nums[1] * sorted_nums[n-1]
