def maximum_segments(n, a, b, c):
    if n < 0 or a < 0 or b < 0 or c < 0:
        return 0
    if a == 0 or b == 0 or c == 0:
        return 0
    if a > n or b > n or c > n:
        return 0

    max_segments = 0

    for i in range(n // a + 1):
        for j in range((n - i * a) // b + 1):
            remaining = n - i * a - j * b
            if remaining >= 0 and remaining % c == 0:
                k = remaining // c
                total = i + j + k
                if total > max_segments:
                    max_segments = total

    return max_segments
```

