    seen = set()

    for item in l1:
        if item in seen:
            continue
        if item in l2:
            common_elements.append(item)
            seen.add(item)

    # Check if the common elements appear in the same relative order in l2
    l2_index = 0
    for item in common_elements:
        # Find the next occurrence of item in l2 starting from l2_index
        found_index = -1
        for i in range(l2_index, len(l2)):
