def rearange_string(S):
    from collections import Counter

    if not S:
        return ""

    counter = Counter(S)
    max_count = max(counter.values())
    length = len(S)

    if max_count > (length + 1) // 2:
        return ""

    chars = []
    for char in sorted(counter.keys()):
        count = counter[char]
        chars.extend([char] * count)

    result = []
    for i in range(length):
        if i % 2 == 0:
            result.append(chars[i // 2])
        else:
            result.append(chars[i // 2 + length // 2])

    return ("", "".join(result))
