def re_arrange(arr, n):
    if n == 0:
        return []

    result = [0] * n
    pos_idx = 0
    neg_idx = 0

    # First pass: count positives and negatives
    for i in range(n):
        if arr[i] >= 0:
            pos_idx += 1
        else:
            neg_idx += 1

    # Second pass: fill result in alternating order
    # Start with the first negative number if available, otherwise first positive
    # The example shows starting with a negative: [-5, 5, -2, 2...]
    # So we alternate: neg, pos, neg, pos...

    i = 0
    while i < n:
        if i % 2 == 0:
            # Even index: negative number
            if neg_idx < n:
                result[i] = arr[neg_idx]
                neg_idx += 1
            else:
                # No more negatives, take positive
                result[i] = arr[pos_idx]
                pos_idx += 1
        else:
            # Odd index: positive number
            if pos_idx < n:
                result[i] = arr[pos_idx]
                pos_idx += 1
            else:
                # No more positives, take negative
                result[i] = arr[neg_idx]
                neg_idx += 1
        i += 1

    return result
