def get_maxgold(gold, m, n):
    if not gold or m == 0 or n == 0:
        return 0

    # Create a DP table with dimensions (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the first column
    for i in range(1, m + 1):
        dp[i][1] = dp[i-1][1] + gold[i-1][0]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(2, n + 1):
            dp[i][j] = gold[i-1][j-1]
            # In the Gold Mine problem, from a cell (i, j), you can move to (i+1, j) or (i+1, j-1)
            # So when computing dp[i][j], we look at the previous row's neighbors: dp[i-1][j] and dp[i-1][j-1]
            if j < n:
                dp[i][j] += max(dp[i-1][j], dp[i-1][j-1])
            else:
                dp[i][j] += dp[i-1][j]

    # Find the maximum value in the last column
    return max(dp[i][n] for i in range(1, m + 1))
```

