def sum_digits_twoparts(N):
    if N < 0:
        N = -N
    if N < 10:
        return sum_digits_single(N)

    max_sum = 0
    # Iterate through split points. 
    # i represents the power of 10 for the second part.
    # i=1 means split after the last digit (part1 = N // 10, part2 = N % 10)
    # i=len(str(N)) means split before the first digit (part1 = 0, part2 = N)
    # This covers all valid splits into two parts (including 0 and N).
    for i in range(1, len(str(N)) + 1):
        part1 = N // (10 ** i)
        part2 = N % (10 ** i)
        current_sum = sum_digits_single(part1) + sum_digits_single(part2)
        if current_sum > max_sum:
            max_sum = current_sum
    return max_sum

