    if not l1 or not l2:
        return False

    # Find common elements in the order they appear in l1
    common_elements = []
    seen = set()

    for item in l1:
        if item in seen:
            continue
        if item in l2:
            common_elements.append(item)
            seen.add(item)

    # Check if the common elements appear in the same relative order in l2
    l2_index = 0
    for item in common_elements:
        # Find the next occurrence of item in l2 starting from l2_index
        found_index = -1
        for i in range(l2_index, len(l2)):
            if l2[i] == item:
                found_index = i
                break

        if found_index == -1:
            return False

        l2_index = found_index + 1

    return True

