import math

def count_Rectangles(radius):
    if radius <= 0:
        return 0

    r_squared = radius * radius
    count = 0

    # Iterate over all possible integer coordinates for the bottom-left corner (x1, y1)
    # and top-right corner (x2, y2) of a rectangle.
    # The rectangle is defined by x1, x2, y1, y2 where x1 < x2 and y1 < y2.
    # All four corners must be inside or on the boundary of the circle.

    # Determine the range of integer coordinates.
    # Since the circle is centered at (0,0), x and y range from -floor(r) to floor(r).
    limit = int(math.floor(radius))

    for x1 in range(-limit, limit + 1):
        for y1 in range(-limit, limit + 1):
            # Check if bottom-left corner is inside
            if x1 * x1 + y1 * y1 > r_squared:
                continue

            for x2 in range(x1 + 1, limit + 1):
                for y2 in range(y1 + 1, limit + 1):
                    # Check if top-right corner is inside
                    if x2 * x2 + y2 * y2 > r_squared:
                        continue

                    # Check if top-left corner is inside
                    if x1 * x1 + y2 * y2 > r_squared:
                        continue

                    # Check if bottom-right corner is inside
                    if x2 * x2 + y1 * y1 > r_squared:
                        continue

                    # If all corners are inside, count this rectangle
                    count += 1

    return count

