def max_profit(price, k):
    if not price or k == 0:
        return 0

    n = len(price)
    if n <= 1:
        return 0

    # If k is large enough, we can do unlimited transactions
    if k >= n // 2:
        profit = 0
        for i in range(1, n):
            if price[i] > price[i-1]:
                profit += price[i] - price[i-1]
        return profit

    # dp[i][j] = max profit with at most j transactions after day i
    # We use a 2D array where dp[i][j] is max profit with at most j transactions after day i
    dp = [[0] * (k + 1) for _ in range(n)]

    for i in range(1, n):
        for j in range(1, k + 1):
            # dp[i][j] = max(dp[i-1][j], price[i] - price[i-1] + dp[i-1][j-1])
            dp[i][j] = max(dp[i-1][j], price[i] - price[i-1] + dp[i-1][j-1])

    return dp[n-1][k]
