    if m < 0 or n < 0 or m > len(cost) - 1 or n > len(cost[0]) - 1:
        return -1

    dp = [[0] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = cost[0][0]

    for i in range(1, m + 1):
        dp[i][0] = dp[i-1][0] + cost[i-1][0]

    for j in range(1, n + 1):
        dp[0][j] = dp[0][j-1] + cost[0][j-1]

